// Website lead capture: demo/fit-check forms on the marketing sites -> a lead
// in the Ericka AI sales pipeline (plumbing_leads, stage new_lead).
//
// BEFORE ACTIVATING, replace the placeholders below:
//   SUPABASE_URL      = https://phtmarvmovozydxipmat.supabase.co
//   SERVICE_KEY       = service_role key (prefer an n8n credential; never export it)
//   SALES_ACCOUNT_ID  = sub_account_id of the "Ericka AI" tenant (your own pipeline)
//
// The forms post JSON from the browser, so the webhook node allows the two
// marketing origins (CORS). Spam guard: a hidden "website" field (honeypot)
// must be empty, and name + phone or email are required.

const SUPABASE_URL = 'PASTE_PROJECT_URL_HERE';
const SERVICE_KEY = 'PASTE_SERVICE_ROLE_KEY_HERE';
const SALES_ACCOUNT_ID = 'PASTE_ERICKA_AI_SUB_ACCOUNT_ID';

const b = items[0].json.body ?? items[0].json;
const clean = (v, max = 500) => String(v ?? '').trim().slice(0, max);

if (clean(b.website)) {
  // Bots fill every field. Pretend success so they don't retry.
  return [{ json: { ok: true } }];
}

const name = clean(b.name, 120);
const phone = clean(b.phone, 40);
const email = clean(b.email, 200);
if (!name || (!phone && !email)) {
  throw new Error('Missing name and a way to reach them.');
}

const details = [
  b.company_name && `Company: ${clean(b.company_name, 200)}`,
  email && `Email: ${email}`,
  b.cost_pain_point && `Biggest cost: ${clean(b.cost_pain_point, 200)}`,
  b.service_area_details && `Notes: ${clean(b.service_area_details, 1000)}`,
  b.fit_answers && `Fit check: ${clean(JSON.stringify(b.fit_answers), 1000)}`,
  `SMS consent: ${b.sms_consent === true ? 'yes' : 'no'}`,
  b.source_page && `Page: ${clean(b.source_page, 200)}`,
].filter(Boolean).join('\n');

await this.helpers.httpRequest({
  method: 'POST',
  url: `${SUPABASE_URL}/rest/v1/plumbing_leads`,
  headers: {
    apikey: SERVICE_KEY,
    Authorization: `Bearer ${SERVICE_KEY}`,
    'Content-Type': 'application/json',
    Prefer: 'return=minimal',
  },
  body: {
    // call_id is the unique key for phone leads; web leads get their own prefix.
    call_id: `web-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    sub_account_id: SALES_ACCOUNT_ID,
    customer_name: name,
    customer_phone: phone,
    customer_address: '',
    plumbing_issue: `Website demo request\n${details}`,
    emergency_level: 'standard',
    pipeline_stage: 'new_lead',
    transcript: null,
  },
  json: true,
});

return [{ json: { ok: true } }];
